const shq = (s: string) => `'${s.replace(/'/g, "'\\''")}'`;

/**
 * Shell that prints the host plugin folder ONLY if the live container both
 * bind-mounts something at TERRARIA_PLUGIN_MOUNT and was started with
 * `-additionalplugins TERRARIA_PLUGIN_MOUNT` — without the flag TShock never
 * looks there, so a file placed in it would be a fake "installed". Prints
 * nothing for a server provisioned before the setupScript carried both.
 */
export function terrariaPluginDirShell(): string {
  return (
    `c=$(docker inspect ${TERRARIA_CONTAINER} --format '{{json .Config.Cmd}}' 2>/dev/null); ` +
    `d=$(docker inspect ${TERRARIA_CONTAINER} --format '{{range .Mounts}}{{if eq .Destination "${TERRARIA_PLUGIN_MOUNT}"}}{{.Source}}{{end}}{{end}}' 2>/dev/null); ` +
    `printf '%s' "$c" | grep -qF -- '"-additionalplugins","${TERRARIA_PLUGIN_MOUNT}"' && [ -n "$d" ] && [ -d "$d" ] && echo "$d"`
  );
