/**
 * The detached install script for one plugin file. Markers (one per line):
 *   NXTP:NODIR | NXTP:DLFAIL | NXTP:NOTDLL — stopped before touching anything
 *   NXTP:SAME — this exact file was already in place (nothing to restart)
 *   NXTP:BOOT:<ok|fail|exited|timeout>  NXTP:NEW:<TShock's "Plugin … initiated." line>
 *   NXTP:WHY:<TShock's own error line>  NXTP:ROLLBACK:<ok|fail|exited|timeout>
 *   NXTP:RESULT:<installed|same|noload|errors|bootfail|exited>   NXTP:END
 *
 * INSTALLED requires a NEW "Plugin X vY (by Z) initiated." line that the
 * previous run didn't have, and no `Plugin "X" has had an unhandled exception`
 * from TSAPI naming that same plugin — attributed by name, so unrelated noise
 * in the log (another plugin's update check failing on a flaky network, say)
 * can't fail a good install. Anything else puts the previous state back.
 */
export function terrariaInstallScript(file: string, url: string): string {
  return [
    `set +e`,
    SHELL_LIB,
    `dir=$( ${terrariaPluginDirShell()} )`,
    `if [ -z "$dir" ]; then echo NXTP:NODIR; echo NXTP:END; exit 0; fi`,
    `f="$dir/${file}"; w=$(mktemp -d)`,
    `if ! curl -fsSL --retry 3 --max-time 180 -o "$w/p" ${shq(url)}; then rm -rf "$w"; echo NXTP:DLFAIL; echo NXTP:END; exit 0; fi`,
    // Every .NET assembly is a PE file ("MZ"). Anything else — an HTML error
    // page, a zip — would only make TShock abort startup.
    `if [ "$(head -c 2 "$w/p")" != "MZ" ]; then rm -rf "$w"; echo NXTP:NOTDLL; echo NXTP:END; exit 0; fi`,
    // Only this installer ever writes nxeon-<slug>.dll, and it only ever
    // leaves one behind after verifying it — the identical file already being
    // there means it's already installed; restarting would prove nothing new.
    `if [ -f "$f" ] && cmp -s "$w/p" "$f"; then rm -rf "$w"; echo NXTP:SAME; echo NXTP:RESULT:same; echo NXTP:END; exit 0; fi`,
    `if nx_running; then was=up; else was=down; fi`,
    `prev=$(nx_started)`,
    `nx_runlog "$prev" | grep -o 'Plugin .* initiated\\.' | sort -u > "$w/before"`,
    // An update keeps the previous copy aside (".nxprev" doesn't end in .dll,
    // so TShock ignores it) so a failed update restores it, not nothing.
    `[ -f "$f" ] && cp -f "$f" "$f.nxprev"`,
    `mv -f "$w/p" "$f"; chmod 644 "$f"`,
    `set -- $(nx_restart_wait); st=$1; ts=$2; echo "NXTP:BOOT:$st"`,
    `res=installed`,
    `if [ "$st" = ok ]; then`,
    `  l=$(nx_runlog "$ts")`,
    `  printf '%s\\n' "$l" | grep -o 'Plugin .* initiated\\.' | sort -u | grep -vxF -f "$w/before" | grep . > "$w/new"`,
    `  sed 's/^/NXTP:NEW:/' "$w/new"`,
    `  sed -n 's/^Plugin \\(.*\\) v[^ ]* (by .*) initiated\\.$/Plugin "\\1" has had an unhandled exception/p' "$w/new" > "$w/pat"`,
    `  if [ ! -s "$w/new" ]; then res=noload`,
    `  elif [ -s "$w/pat" ] && printf '%s\\n' "$l" | grep -F -f "$w/pat" > "$w/bad"; then res=errors; head -1 "$w/bad" | sed 's/^/NXTP:WHY:/'; fi`,
    `else`,
    `  res=bootfail; [ "$st" = exited ] && res=exited`,
    `  nx_runlog "$ts" | grep -E -m1 'Could not load file or assembly|Could not load type|Could not find a part of the path|Failed to load assembly|has thrown an exception during initialization' | sed 's/^/NXTP:WHY:/'`,
    // A self-shutdown usually says why just before it goes (e.g. BanGuard's
    // "Error validating BanGuard API key. Please check your configuration.").
    `  [ "$st" = exited ] && nx_runlog "$ts" | grep -i -E 'error|exception|fail|invalid' | grep -v -E 'Error Logging Enabled|improperly shut down' | tail -1 | sed 's/^/NXTP:WHY:/'`,
    `fi`,
    `if [ "$res" != installed ]; then`,
    `  rm -f "$f"; [ -f "$f.nxprev" ] && mv -f "$f.nxprev" "$f"`,
    `  set -- $(nx_restart_wait); echo "NXTP:ROLLBACK:$1"`,
    `else`,
    `  rm -f "$f.nxprev"`,
    `fi`,
    // Started it only to verify — leave it the way the customer had it.
    `[ "$was" = down ] && systemctl stop ${TERRARIA_CONTAINER} >/dev/null 2>&1`,
    `rm -rf "$w"`,
    `echo "NXTP:RESULT:$res"`,
    `echo NXTP:END`,
  ].join("\n");
}

/** Detached removal: delete the file, and restart (if running) so "removed"
 *  is true of the running server — TShock only unloads plugins by restarting. */
export function terrariaRemoveScript(file: string): string {
  return [
    `set +e`,
    SHELL_LIB,
    `dir=$( ${terrariaPluginDirShell()} )`,
    `if [ -n "$dir" ]; then`,
    `  rm -f "$dir/${file}" "$dir/${file}.nxprev"`,
    `  if nx_running; then set -- $(nx_restart_wait); echo "NXTP:BOOT:$1"; fi`,
    `fi`,
    `echo NXTP:REMOVED`,
    `echo NXTP:END`,
  ].join("\n");
}

export type TerrariaPluginResult = { ok: boolean; version?: string; error?: string };

const ROLLED_BACK = "It was removed again and your server was restarted without it.";

/** Turn the install script's markers into the customer-facing outcome. */
export function parseTerrariaInstall(out: string): TerrariaPluginResult {
  if (out.includes("NXTP:NODIR")) return { ok: false, error: TERRARIA_NOT_ENABLED };
  if (out.includes("NXTP:DLFAIL")) return { ok: false, error: "Download failed on the server." };
  if (out.includes("NXTP:NOTDLL")) return { ok: false, error: "The download wasn't a TShock plugin (.dll) — install it by hand in Files." };

  const result = /NXTP:RESULT:(\w+)/.exec(out)?.[1];
  const rollback = /NXTP:ROLLBACK:(\w+)/.exec(out)?.[1];
  const why = /NXTP:WHY:(.+)/.exec(out)?.[1]?.trim().slice(0, 220);
  const rollbackNote =
    rollback && rollback !== "ok"
      ? " Your server didn't come back up cleanly after removing it — check Console → Logs, or contact support."
      : "";
  switch (result) {
    case "installed": {
      // "Plugin QoL v1.3.3.0 (by Soofa) initiated." → "1.3.3.0"
      const version = /NXTP:NEW:Plugin .+? v(\S+) \(by /.exec(out)?.[1];
      return { ok: true, version };
    }
    case "same":
      return { ok: true };
    case "noload":
      return { ok: false, error: `TShock didn't load it — it isn't built for this server's TShock version. ${ROLLED_BACK}${rollbackNote}` };
    case "errors":
      return {
        ok: false,
        error: `It loaded but crashed while your server started${why ? ` (${why})` : ""}. ${ROLLED_BACK}${rollbackNote}`,
      };
    case "exited":
      return {
        ok: false,
        error: `Your server shut itself down right after starting with it installed${why ? ` (${why})` : ""} — it may need its own setup (an API key, say) first. ${ROLLED_BACK}${rollbackNote}`,
      };
    case "bootfail": {
      const boot = /NXTP:BOOT:(\w+)/.exec(out)?.[1];
      const reason = boot === "timeout" ? "it didn't finish starting within about 4 minutes" : why ? `TShock: ${why}` : "TShock aborted startup";
      return { ok: false, error: `Your server couldn't start with it installed (${reason}). ${ROLLED_BACK}${rollbackNote}` };
    }
    default:
      return { ok: false, error: "The plugin change didn't report a result — check Console → Logs." };
  }
}

export function parseTerrariaRemove(out: string): TerrariaPluginResult {
  return out.includes("NXTP:REMOVED") ? { ok: true } : { ok: false, error: "Couldn't confirm the plugin was removed." };
}
