/**
 * Worker glue between Minecraft provisioning/reinstall/settings-apply and the
 * mirror (lib/mcjars). Side-effect-light: the only writes are McJarPin rows.
 * Every function here swallows its own errors and returns "no pin" — the mirror
 * must never be the reason a provision or settings apply fails; without a pin
 * everything behaves exactly as before (itzg downloads from upstream).
 */
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { planPin, type PlanResult } from "../lib/mcjars/plan";
import { variantType } from "../lib/mcjars/runner";
import type { PinPlan } from "../lib/mcjars/pin";

type ServerLike = {
  id: string;
  gameVariant?: string | null;
  gameConfig?: unknown;
  osTemplate?: { family?: string | null } | null;
  gamePlan?: { gameFamily?: string | null } | null;
};

export function isMinecraft(server: ServerLike): boolean {
  return (server.gamePlan?.gameFamily ?? server.osTemplate?.family) === "minecraft";
}

export function wantedVersion(server: ServerLike): string {
  const v = (server.gameConfig as Record<string, unknown> | null)?.VERSION;
  return typeof v === "string" && v ? v : "1.21.1";
}

async function officialFailing(type: string): Promise<boolean> {
  try {
    const row = await db.mcMirrorProvider.findUnique({ where: { key: type }, select: { failingSince: true } });
    return !!row?.failingSince;
  } catch {
    return false;
  }
}

/** Decide the pin for a server (desired type/version from its row unless overridden). Never throws. */
export async function resolveServerPin(
  server: ServerLike,
  override: { type?: string; version?: string; build?: string | null } = {},
): Promise<PlanResult> {
  if (process.env.MC_MIRROR_PIN === "0") return { plan: null, reason: "pinning disabled (MC_MIRROR_PIN=0)" };
  try {
    const type = override.type ?? variantType(server.gameVariant);
    return await planPin({
      type,
      version: override.version ?? wantedVersion(server),
      requestedBuild: override.build ?? null,
      allowSelfBuilt: !!override.build || (await officialFailing(type)),
    });
  } catch (e) {
    return { plan: null, reason: `pin planning error: ${e instanceof Error ? e.message : String(e)}` };
  }
}

export async function recordPin(
  serverId: string,
  rec: { type: string; mcVersion: string; plan: PinPlan | null; state: "PLANNED" | "ACTIVE" | "FALLBACK"; source?: string; detail?: string; jarFile?: string; sha256?: string; build?: string },
): Promise<void> {
  try {
    const data = {
      type: rec.type,
      mcVersion: rec.plan?.mcVersion ?? rec.mcVersion,
      build: rec.plan?.build ?? rec.build ?? null,
      fileName: rec.plan?.fileName ?? rec.jarFile ?? null,
      sha256: rec.plan?.sha256 ?? rec.sha256 ?? null,
      source: rec.source ?? rec.plan?.source ?? "upstream",
      state: rec.state,
      detail: rec.detail?.slice(0, 500) ?? null,
    };
    await db.mcJarPin.upsert({ where: { serverId }, create: { serverId, ...data }, update: data });
  } catch (e) {
    console.error(`[mcjar-pin] could not record pin for ${serverId}`, e);
  }
}

/**
 * PROVISION / GAME_REINSTALL hook: returns the pin plan to bake into the
 * cloud-init / reinstall script (worker/game-variant.ts applies it), or null.
 * Records PLANNED (or FALLBACK with the reason) for the admin page.
 */
export async function mcJarPinForSetup(server: ServerLike): Promise<PinPlan | null> {
  if (!isMinecraft(server)) return null;
  const r = await resolveServerPin(server);
  if (SANDBOX && !r.plan) return null;
  const type = variantType(server.gameVariant);
  if (r.plan) {
    await recordPin(server.id, { type, mcVersion: r.plan.mcVersion, plan: r.plan, state: "PLANNED", detail: "staged by the setup script; falls back to upstream on the guest if the download fails" });
    console.log(`[mcjar-pin] ${server.id}: pinning ${r.plan.type} ${r.plan.mcVersion} build ${r.plan.build} from the mirror`);
    return r.plan;
  }
  await recordPin(server.id, { type, mcVersion: wantedVersion(server), plan: null, state: "FALLBACK", detail: r.reason });
  console.log(`[mcjar-pin] ${server.id}: no mirror pin (${r.reason}) — upstream behaviour`);
  return null;
}
/**
 * Pinning a Minecraft server to an exact mirrored jar — PURE helpers shared by
 * provisioning (worker/game-variant.ts), settings-apply (worker/game-config.ts)
 * and the rescue tool (scripts/mc-pin-jar.ts). Tested in test/mcjars.test.ts.
 *
 * WHY (incident 2026-10-01): itzg/minecraft-server re-resolves and re-downloads
 * the server jar from the internet on EVERY container start (TYPE=PAPER →
 * fill.papermc.io, VANILLA → Mojang manifest, …). PaperMC's whole download API
 * returned 503 for hours and a customer's Paper server crash-looped 100+ times
 * on plain restarts. Pinned, the jar lives on the server's own /opt/mc volume
 * and the image is told to use that file — restarts never contact upstream.
 *
 * Per-type env, verified against the itzg scripts (master, 2026-10-01 —
 * scripts/start-deploy*, the java25 tag is built from it):
 *   vanilla  TYPE=CUSTOM  CUSTOM_SERVER=<jar>  FAMILY=VANILLA     (start-deployCustom; FAMILY override honoured)
 *   paper    TYPE=PAPER   PAPER_CUSTOM_JAR=<jar>                  (start-deployPaper: skips mc-image-helper install-paper)
 *   folia    TYPE=FOLIA   PAPER_CUSTOM_JAR=<jar>                  (start-deployFolia execs start-deployPaper)
 *   purpur   TYPE=CUSTOM  CUSTOM_SERVER=<jar>  FAMILY=SPIGOT      (start-deployPurpur has no local-file option)
 *   fabric   TYPE=FABRIC  FABRIC_LAUNCHER=<jar>                   (install-fabric-loader --from-local-file)
 *   forge    TYPE=FORGE   FORGE_INSTALLER=<jar>                   (ProvidedInstallerResolver: version read from the jar)
 *   neoforge TYPE=NEOFORGE NEOFORGE_INSTALLER=<jar>
 * plus, for the Paper family, SKIP_DOWNLOAD_DEFAULTS=true: start-deployPaper
 * otherwise fetches default bukkit/spigot/paper-global.yml from GitHub on every
 * start (warning-only, but a pointless upstream call + delay; Paper generates
 * its own defaults). NXEON_MCJAR=<type>:<version>:<build>:<sha256> is a marker
 * the platform reads back from `docker inspect` to know what is running.
 */
import type { McType } from "./types";

/** Host path (bind-mounted to /data in the `mc` container). */
export const HOST_JAR_DIR = "/opt/mc/.nxeon/jars";
export const CONTAINER_JAR_DIR = "/data/.nxeon/jars";
export const PIN_ENV_FILE = "/root/mc-pin.env";

/** Env keys this module owns — stripped before writing a new pin (or the upstream fallback). */
export const PIN_KEYS = [
  "TYPE",
  "CUSTOM_SERVER",
  "PAPER_CUSTOM_JAR",
  "FABRIC_LAUNCHER",
  "FORGE_INSTALLER",
  "NEOFORGE_INSTALLER",
  "FAMILY",
  "SKIP_DOWNLOAD_DEFAULTS",
  "NXEON_MCJAR",
  // stale upstream selectors that would fight a pin
  "PAPER_BUILD",
  "PAPERBUILD",
  "PAPER_DOWNLOAD_URL",
  "PURPUR_BUILD",
  "PURPUR_DOWNLOAD_URL",
  "FABRIC_LOADER_VERSION",
  "FABRIC_LAUNCHER_VERSION",
  "FABRIC_INSTALLER_VERSION",
  "FABRIC_LAUNCHER_URL",
  "FORGE_VERSION",
  "FORGE_INSTALLER_URL",
  "NEOFORGE_VERSION",
] as const;

export const PINNABLE_TYPES = ["vanilla", "paper", "folia", "purpur", "fabric", "forge", "neoforge"] as const;
export type PinnableType = (typeof PINNABLE_TYPES)[number];
export function isPinnable(t: string): t is PinnableType {
  return (PINNABLE_TYPES as readonly string[]).includes(t);
}

export interface PinPlan {
  type: PinnableType;
  mcVersion: string;
  build: string;
  fileName: string;
  sha256: string;
  size: number | null;
  url: string;
  channel: string;
  source: "mirror" | "self-built" | "guest-local";
}

const SAFE_FILE = /^[A-Za-z0-9][A-Za-z0-9._+-]{0,150}\.jar$/;
const SAFE_VERSION = /^[0-9A-Za-z][0-9A-Za-z._+-]{0,40}$/;
