import { createHmac, timingSafeEqual } from "node:crypto";
import { publicBaseUrl } from "./config";

export const ROUTE_PREFIX = "/api/mcjars";

function key(): Buffer {
  const explicit = process.env.MC_MIRROR_URL_SECRET;
  if (explicit && explicit.length >= 16) return Buffer.from(explicit, "utf8");
  const base = process.env.AUTH_SECRET;
  if (!base) throw new Error("mc mirror: no MC_MIRROR_URL_SECRET or AUTH_SECRET available to sign URLs");
  return createHmac("sha256", base).update("nxeon-mcjars-url-v1").digest();
}

export function tokenFor(type: string, mcVersion: string, file: string): string {
  return createHmac("sha256", key()).update(`v1:${type}/${mcVersion}/${file}`).digest("base64url").slice(0, 32);
