/**
 * The mirror is usable only if the dataset root already exists (we never make it).
 * Creates `<root>` (the `minecraft/` child) when — and only when — its parent exists.
 */
export async function mirrorReady(opts: { create?: boolean } = {}): Promise<boolean> {
  if (mirrorDisabled()) return false;
  const root = mirrorRoot();
  if (readyCache && readyCache.root === root && Date.now() - readyCache.at < 30_000 && (readyCache.ok || !opts.create)) {
    return readyCache.ok;
  }
  let ok = false;
  try {
    ok = (await fs.stat(root)).isDirectory();
  } catch {
    if (opts.create) {
      try {
        const parent = path.dirname(root);
        if ((await fs.stat(parent)).isDirectory()) {
          await fs.mkdir(root, { mode: 0o755 }); // NOT recursive: parent must already exist
          ok = true;
        }
      } catch {
        ok = false;
      }
    }
  }
  readyCache = { at: Date.now(), ok, root };
  return ok;
}

/** For tests: forget the cached readiness probe. */
export function _resetReadyCache(): void {
  readyCache = null;
}

/** Filesystem usage of the dataset holding the mirror (ZFS reports the quota as the size). */
export async function datasetUsage(): Promise<{ sizeBytes: number; freeBytes: number; usedPct: number } | null> {
  try {
    const st = await fs.statfs(mirrorRoot());
    const size = Number(st.blocks) * Number(st.bsize);
    const free = Number(st.bavail) * Number(st.bsize);
    if (!size) return null;
    return { sizeBytes: size, freeBytes: free, usedPct: Math.round(((size - free) / size) * 1000) / 10 };
  } catch {
    return null;
  }
}
