/**
 * Version helpers shared by providers, availability checks and the UI.
 * Pure — safe to import from client components.
 */

/** "1.21.11" / "26.2" → [1,21,11] / [26,2]; null for anything non-numeric ("26.4-snapshot-1", "LATEST"). */
export function parseRelease(v: string): number[] | null {
  if (!/^\d+(\.\d+){0,3}$/.test(v)) return null;
  return v.split(".").map(Number);
}

/** Compare two release strings (numeric dotted). Non-numeric strings sort below numeric ones, then lexically. */
export function compareMcVersions(a: string, b: string): number {
  const pa = parseRelease(a);
  const pb = parseRelease(b);
  if (pa && pb) {
    const len = Math.max(pa.length, pb.length);
    for (let i = 0; i < len; i++) {
      const d = (pa[i] ?? 0) - (pb[i] ?? 0);
      if (d !== 0) return d;
    }
    return 0;
  }
  if (pa) return 1;
  if (pb) return -1;
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Newest-first sort. */
export function sortVersionsDesc(vs: string[]): string[] {
  return [...vs].sort((a, b) => compareMcVersions(b, a));
}

/** Compare dotted build/loader versions like "52.1.16", "0.19.5", "21.1.209", "2633". Numeric-aware. */
export function compareBuilds(a: string, b: string): number {
  const ta = a.split(/[.+-]/);
  const tb = b.split(/[.+-]/);
  const len = Math.max(ta.length, tb.length);
  for (let i = 0; i < len; i++) {
    const x = ta[i] ?? "";
    const y = tb[i] ?? "";
    const nx = /^\d+$/.test(x) ? Number(x) : NaN;
    const ny = /^\d+$/.test(y) ? Number(y) : NaN;
    if (!Number.isNaN(nx) && !Number.isNaN(ny)) {
      if (nx !== ny) return nx - ny;
    } else if (x !== y) {
      // a missing segment (shorter) sorts first; "beta" sorts before numbers
      if (x === "") return -1;
      if (y === "") return 1;
      if (!Number.isNaN(nx)) return 1;
      if (!Number.isNaN(ny)) return -1;
      return x < y ? -1 : 1;
    }
  }
  return 0;
}

