  const t = facts.tshock.find((v) => tshockMatches(v, want.tshock));
  const g = facts.terraria.find((v) => compareDotted(v, want.terraria) === 0);
  if (!t) return { ok: false, reason: `TShock ${want.tshock} was not confirmed in the server log${facts.tshock.length ? ` (it reported ${facts.tshock[0]})` : ""}.` };
  if (!g) return { ok: false, reason: `Terraria ${want.terraria} was not confirmed in the server log${facts.terraria.length ? ` (it reported ${facts.terraria[0]})` : ""}.` };
  if (!facts.serverStarted) return { ok: false, reason: "The world was not reported as loaded yet." };
  return { ok: true, tshock: t, terraria: g };
}

// ---------------------------------------------------------------------------
// Drift (report only)
// ---------------------------------------------------------------------------

export type DriftRow = {
  status: "current" | "behind" | "legacy" | "ahead" | "unknown";
  /** Release the container is configured for ("6.1.0" for legacy), or null. */
  configured: string | null;
  /** What the log says is actually running, if anything was readable. */
  logged: string | null;
  wanted: string;
  detail: string;
};

export function judgeDrift(input: { image: string | null; logFacts?: TerrariaLogFacts | null; wanted?: string }): DriftRow {
  const wanted = input.wanted ?? TERRARIA_PINNED_VERSION;
  if (!input.image) return { status: "unknown", configured: null, logged: null, wanted, detail: "no terraria container found" };
  const logged = input.logFacts?.tshock.length ? input.logFacts.tshock[input.logFacts.tshock.length - 1] : null;
  if (isLegacyTerrariaImage(input.image)) {
    return { status: "legacy", configured: TERRARIA_LEGACY_VERSIONS.tshock, logged, wanted, detail: `legacy ryshe/terraria image (TShock ${TERRARIA_LEGACY_VERSIONS.tshock} / Terraria ${TERRARIA_LEGACY_VERSIONS.terraria})` };
  }
  const configured = versionFromImage(input.image);
  if (!configured) return { status: "unknown", configured: null, logged, wanted, detail: `unrecognised image ${input.image}` };
  const c = compareDotted(configured, wanted);
  const status = c === 0 ? "current" : c < 0 ? "behind" : "ahead";
  const mismatch = logged && !tshockMatches(logged, configured) ? ` (log says ${logged}: restart pending?)` : "";
  return { status, configured, logged, wanted, detail: `${input.image}${mismatch}` };
}

