/**
 * On-disk mirror store.
 *
 *   <root>/manifest.json                     global summary (atomic write)
 *   <root>/<type>/index.json                 per-type index: versions, builds, sha256, size,
 *                                            source URL, fetchedAt, channel (atomic write)
 *   <root>/<type>/<mcVersion>/<file>         the artifact — immutable once written
 *   <root>/.tmp/                             in-flight downloads (same FS → atomic rename)
 *   <root>/.quarantine/                      files that failed a re-hash (kept for forensics)
 *
 * Invariants:
 *  - a file is written ONLY by rename from .tmp after its sha256 (and the
 *    upstream digest, when published) verified; it is never rewritten in place.
 *    If upstream later serves different bytes under the same name, the existing
 *    file is kept and the conflict is recorded ("immutable-conflict").
 *  - every path that leaves this module went through `safeJoin`, which only
 *    accepts allowlisted segments and re-checks containment after resolve().
 *  - index.json is the source of truth for "what is mirrored" — the serving
 *    route and the provisioning planner read it without needing the DB.
 */
import { createHash, randomBytes } from "node:crypto";
import { createReadStream, createWriteStream } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { Readable, Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import { mirrorRoot, tmpDir } from "./config";
import { HttpError, type McHttp } from "./http";
import type { Candidate, GlobalManifest, HashAlgo, IndexBuild, IndexVersion, McType, ProviderResult, TypeIndex } from "./types";
import { isMcType } from "./types";
import { compareBuilds, sortVersionsDesc } from "./versions";

export const VERSION_RE = /^[0-9A-Za-z][0-9A-Za-z._+-]{0,40}$/;
export const FILE_RE = /^[A-Za-z0-9][A-Za-z0-9._+-]{0,150}\.(jar|zip)$/;
export const SHA256_RE = /^[a-f0-9]{64}$/;
/** Hard per-file ceiling (Bedrock zips are ~100 MB; the largest Java jar today is ~70 MB). */
export const MAX_FILE_BYTES = 400 * 1024 * 1024;

export function validSegment(kind: "type" | "version" | "file", s: string): boolean {
  if (typeof s !== "string" || s.includes("..") || s.includes("/") || s.includes("\\") || s.includes("\0")) return false;
  if (kind === "type") return isMcType(s);
  if (kind === "version") return VERSION_RE.test(s);
  return FILE_RE.test(s);
}

/** Join under the mirror root, refusing anything that isn't an allowlisted segment or escapes the root. */
export function safeJoin(root: string, type: string, version?: string, file?: string): string {
  if (!validSegment("type", type)) throw new Error("bad type");
  if (version !== undefined && !validSegment("version", version)) throw new Error("bad version");
  if (file !== undefined && !validSegment("file", file)) throw new Error("bad file");
  const base = path.resolve(root);
  const parts = [base, type, ...(version !== undefined ? [version] : []), ...(file !== undefined ? [file] : [])];
  const abs = path.resolve(...parts);
  if (abs !== base && !abs.startsWith(base + path.sep)) throw new Error("path escapes mirror root");
  return abs;
}

