    for (const a of r.assets ?? []) {
      const m = ASSET_RE.exec(a.name ?? "");
      if (m && norm(m[1]) === tag) {
        terraria = m[2];
        break;
      }
    }
    if (!terraria) terraria = terrariaKnown(tag)?.terraria ?? null;
    if (!terraria) continue; // cannot say which Terraria it targets -> do not offer
    seen.add(tag);
    out.push({
      tshock: tag,
      terraria,
      released: String(r.published_at ?? "").slice(0, 10),
      notes: plainNotes(r.body),
      verified: !!terrariaKnown(tag),
    });
  }
  out.sort((a, b) => compareDotted(b.tshock, a.tshock));
  return out.map((e, i) => ({ ...e, recommended: i === 0 }));
}

export function recommendedOf(cat: TerrariaCatalogueEntry[]): TerrariaCatalogueEntry | null {
  return cat.find((e) => e.recommended) ?? null;
}

/** Label for the Settings picker: "TShock 6.2.1 - Terraria 1.4.5.8 (recommended)". */
export function versionLabel(e: Pick<TerrariaCatalogueEntry, "tshock" | "terraria" | "recommended">): string {
  return `TShock ${e.tshock} - Terraria ${e.terraria}${e.recommended ? " (recommended)" : ""}`;
}

/** What the version picker may offer a server currently on `current` (never a lower Terraria version). */
export function offerableVersions(cat: TerrariaCatalogueEntry[], current: { tshock: string; terraria: string } | null): TerrariaCatalogueEntry[] {
  if (!current) return cat;
  return cat.filter((e) => compareDotted(e.terraria, current.terraria) >= 0 && !(compareDotted(e.terraria, current.terraria) === 0 && compareDotted(e.tshock, current.tshock) < 0));
}
