/**
 * Local mirror of the TShock images (docker-archive tarballs) so provisioning and updates
 * never depend on GitHub or a container registry being reachable, and old versions stay
 * available. Same shape as the Minecraft mirror (lib/mcjars): files live on the big `tank`
 * pool, are written only by rename after their sha256 is computed, are served to game VMs
 * through a tokenised, rate-limited route, and are never listed.
 *
 *   <root>/index.json                     catalogue + per-version file facts (atomic write)
 *   <root>/<version>/tshock-<version>.tar docker-archive of ghcr.io/pryaxis/tshock:<version> (linux/amd64)
 *   <root>/.tmp/                          in-flight downloads (same FS)
 *
 *   root = TERRARIA_MIRROR_DIR, else <NXLABS_MIRROR_DIR or /tank/nxlabs-mirror>/terraria.
 *   Like the Minecraft mirror the dataset root is NEVER created by code: missing => mirror off,
 *   every consumer falls back to a normal registry pull.
 *
 * Retention: nothing is deleted automatically (a TShock image is ~110 MB). `planKeep` only
 * decides what the SWEEP may stop downloading; `mayEvict` is the single rule for any future
 * eviction: never a version a server runs or is configured for, never the recommended one.
 */
import fs from "node:fs/promises";
import path from "node:path";
import { datasetRoot, publicBaseUrl } from "./mcjars/config";
import { tokenFor, tokenValid } from "./mcjars/urls";
import type { TerrariaCatalogueEntry } from "./terraria-versions";

export const TERRARIA_ROUTE_PREFIX = "/api/tshock-image";
export const TERRARIA_MIRROR_TYPE = "terraria"; // HMAC domain separator (shared helper with the mc mirror)

export type MirrorFileFacts = {
  file: string;
  size: number;
  sha256: string;
  /** Image id read back from the tarball's config after download. */
  imageId: string | null;
  mirroredAt: string;
};
export type TerrariaIndexVersion = TerrariaCatalogueEntry & { mirror: MirrorFileFacts | null; lastError?: string | null };
export type TerrariaIndex = {
  schema: 1;
  updatedAt: string;
  /** Last sweep outcome, shown in the admin page / drift report. */
  lastSweep?: { at: string; ok: boolean; error?: string | null };
  versions: Record<string, TerrariaIndexVersion>;
};

export function terrariaMirrorRoot(): string {
  return process.env.TERRARIA_MIRROR_DIR || path.join(datasetRoot(), "terraria");
}
export const terrariaMirrorDisabled = (): boolean => process.env.TERRARIA_MIRROR_DISABLED === "1";

const VERSION_RE = /^\d+\.\d+\.\d+$/;
export const terrariaFileName = (version: string) => `tshock-${version}.tar`;
const FILE_RE = /^tshock-\d+\.\d+\.\d+\.tar$/;

export function validTerrariaSegment(kind: "version" | "file", s: string): boolean {
  if (typeof s !== "string" || s.includes("..") || s.includes("/") || s.includes("\\") || s.includes("\0")) return false;
  return kind === "version" ? VERSION_RE.test(s) : FILE_RE.test(s);
}

export function terrariaSafeJoin(root: string, version?: string, file?: string): string {
  if (version !== undefined && !validTerrariaSegment("version", version)) throw new Error("bad version");
  if (file !== undefined && !validTerrariaSegment("file", file)) throw new Error("bad file");
  const base = path.resolve(root);
  const abs = path.resolve(base, ...(version !== undefined ? [version] : []), ...(file !== undefined ? [file] : []));
  if (abs !== base && !abs.startsWith(base + path.sep)) throw new Error("path escapes mirror root");
  return abs;
}

export async function readTerrariaIndex(root = terrariaMirrorRoot()): Promise<TerrariaIndex | null> {
  try {
    const j = JSON.parse(await fs.readFile(path.join(root, "index.json"), "utf8")) as TerrariaIndex;
    return j && j.schema === 1 && j.versions ? j : null;
  } catch {
    return null;
  }
}

export async function writeTerrariaIndex(ix: TerrariaIndex, root = terrariaMirrorRoot()): Promise<void> {
  await fs.mkdir(root, { recursive: false }).catch(async () => {
    // the dataset parent must already exist; mkdir(non-recursive) only creates the leaf
    await fs.stat(path.dirname(root));
    await fs.mkdir(root);
  });
  const tmp = path.join(root, `.index.${process.pid}.${Date.now()}.tmp`);
  await fs.writeFile(tmp, JSON.stringify(ix, null, 2));
  await fs.rename(tmp, path.join(root, "index.json"));
}

/** Guest-facing URL for one mirrored image. */
export function terrariaMirrorPath(version: string, file = terrariaFileName(version)): string {
  return `${TERRARIA_ROUTE_PREFIX}/${tokenFor(TERRARIA_MIRROR_TYPE, version, file)}/${version}/${file}`;
}
export function terrariaMirrorUrl(version: string, file = terrariaFileName(version)): string {
  return `${publicBaseUrl()}${terrariaMirrorPath(version, file)}`;
}
export const terrariaTokenValid = (token: string, version: string, file: string) => tokenValid(token, TERRARIA_MIRROR_TYPE, version, file);

/** Mirrored + verifiable entry for a version (null when it is not mirrored). */
export async function mirroredEntry(version: string, root = terrariaMirrorRoot()): Promise<TerrariaIndexVersion | null> {
  const ix = await readTerrariaIndex(root);
  const v = ix?.versions[version];
  if (!v?.mirror) return null;
  try {
    const st = await fs.lstat(terrariaSafeJoin(root, version, v.mirror.file));
    return st.isFile() && st.size === v.mirror.size ? v : null;
  } catch {
    return null;
  }
}

/** The single eviction rule. `inUse` = every TShock version any server runs or is configured for. */
export function mayEvict(version: string, opts: { inUse: Set<string>; recommended: string | null }): boolean {
  return !opts.inUse.has(version) && version !== opts.recommended;
}

/** Versions the sweep keeps mirrored: recommended + newest `keepNewest` + every in-use one. */
export function planKeep(cat: TerrariaCatalogueEntry[], opts: { inUse: Set<string>; keepNewest: number }): string[] {
  const keep = new Set<string>(opts.inUse);
  cat.slice(0, Math.max(1, opts.keepNewest)).forEach((e) => keep.add(e.tshock));
  const rec = cat.find((e) => e.recommended);
  if (rec) keep.add(rec.tshock);
  return cat.filter((e) => keep.has(e.tshock)).map((e) => e.tshock);
}
