/**
 * Read-only serving of mirrored TShock images to game VMs. Only a file that (a) carries a valid
 * per-file HMAC token, (b) is listed as mirrored in index.json and (c) resolves inside the mirror
 * root is ever opened; everything else is a plain 404. Single-range support, strong ETag = sha256,
 * per-client rate limit, global cap on concurrent streams. Mirrors lib/mcjars/serve.ts.
 */
import fs from "node:fs";
import fsp from "node:fs/promises";
import { Readable } from "node:stream";
import { parseRange } from "./mcjars/serve";
import { checkRateLimit, clientIp } from "./rate-limit";
import { readTerrariaIndex, terrariaMirrorRoot, terrariaSafeJoin, terrariaTokenValid, validTerrariaSegment } from "./terraria-mirror";

export const TERRARIA_MAX_STREAMS = 6;
const RATE = { max: 60, windowMs: 10 * 60_000 };
let active = 0;
const notFound = () => new Response("Not found", { status: 404, headers: { "Cache-Control": "no-store" } });

export async function serveTerrariaImage(req: Request, segments: string[], opts: { root?: string; rateLimit?: boolean } = {}): Promise<Response> {
  if (segments.length !== 3) return notFound();
  const [token, version, file] = segments;
  if (!validTerrariaSegment("version", version) || !validTerrariaSegment("file", file)) return notFound();
  if (!terrariaTokenValid(token, version, file)) return notFound();
  if (opts.rateLimit !== false) {
    const rl = checkRateLimit(`tshock-image:${clientIp(req.headers)}`, RATE);
    if (!rl.ok) return new Response("Too many requests", { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } });
  }
  const root = opts.root ?? terrariaMirrorRoot();
  const m = (await readTerrariaIndex(root))?.versions[version]?.mirror;
  if (!m || m.file !== file) return notFound();
  let abs: string;
  let size: number;
  try {
    abs = terrariaSafeJoin(root, version, file);
    const st = await fsp.lstat(abs);
    if (!st.isFile() || st.size !== m.size) return notFound();
    size = st.size;
  } catch {
    return notFound();
  }
  const etag = `"${m.sha256}"`;
  const base: Record<string, string> = {
    ETag: etag,
    "Accept-Ranges": "bytes",
    "Cache-Control": "private, max-age=31536000, immutable",
    "Content-Type": "application/x-tar",
    "Content-Disposition": `attachment; filename="${file}"`,
    "X-Content-Type-Options": "nosniff",
    "X-Nxeon-Sha256": m.sha256,
  };
  const inm = req.headers.get("if-none-match");
  if (inm && inm.split(",").map((s) => s.trim().replace(/^W\//, "")).includes(etag)) return new Response(null, { status: 304, headers: base });
  const range = parseRange(req.headers.get("range"), size);
  if (range === "invalid") return new Response(null, { status: 416, headers: { ...base, "Content-Range": `bytes */${size}` } });
  const start = range ? range.start : 0;
  const end = range ? range.end : size - 1;
  const headers = { ...base, "Content-Length": String(end - start + 1), ...(range ? { "Content-Range": `bytes ${start}-${end}/${size}` } : {}) };
  const status = range ? 206 : 200;
  if (req.method === "HEAD") return new Response(null, { status, headers });
  if (active >= TERRARIA_MAX_STREAMS) return new Response("Busy", { status: 503, headers: { "Retry-After": "15", "Cache-Control": "no-store" } });
  active++;
  let released = false;
  const release = () => {
    if (!released) {
      released = true;
      active--;
    }
  };
  const stream = fs.createReadStream(abs, { start, end });
  stream.on("close", release);
  stream.on("error", release);
  return new Response(Readable.toWeb(stream) as unknown as ReadableStream, { status, headers });
}

export const _terrariaActiveStreams = () => active;
