import type { Guest } from "./game-config-appliers/types";
import { shq } from "./game-config-appliers/types";
import { recreateWithEnv } from "./game-config-appliers/kit/env-recreate";
import {
  TERRARIA_CONTAINER,
  TERRARIA_LEGACY_VERSIONS,
  isLegacyTerrariaImage,
  judgeDrift,
  judgeRunningVersions,
  parseTerrariaLog,
  terrariaCmdIsOfficial,
  terrariaHostDirOfficial,
  terrariaImageByDigest,
  terrariaImageRef,
  terrariaKnown,
  terrariaOfficialBinds,
  terrariaOfficialCmd,
  terrariaWorldFileOf,
  updateDirection,
  versionFromImage,
  type DriftRow,
} from "../lib/terraria-image";

/**
 * Terraria image UPDATE (and legacy -> official image MIGRATION) for ONE server, through its guest.
 * Contract and reasons: lib/terraria-image.ts. Pure of DB/SSH: everything goes through `Guest`, so
 * test/terraria-update.test.ts drives it against fakes.
 *
 * Order of events (each step either completes or leaves the server exactly as it was):
 *   1. read the container; refuse a downgrade (a 1.4.5.8-saved world may not load in 1.4.5.6)
 *   2. space check, then get the target image onto the guest (local mirror first, registry
 *      fallback; image id verified against the pinned table either way) — nothing stopped yet
 *   3. recreateWithEnv: stop, keep the old container as `terraria-old`, BACK UP the whole data
 *      folder while the game is stopped (copy + diff verified), create the new container with
 *      the same ports/volumes (mapped to the new image's mount points), start it only if the
 *      customer had it running, wait for the port (slow-start window), read it back, then check
 *      the container's own log for the running TShock/Terraria versions and a loaded world
 *   4. ANY failure: new container removed, old container renamed back, data folder restored from
 *      the backup if the new one had been started, old container restarted if it was running.
 * A server the customer stopped is recreated but never started (its versions are then proven on
 * its next start; the drift report shows them).
 */

export type UpdateTarget = {
  tshock: string;
  terraria: string;
  /** Image id expected after load/pull (lib/terraria-image.ts table); null = not verifiable. */
  imageId: string | null;
  indexDigest: string | null;
  /** Local mirror copy, when the mirror has it. */
  mirror?: { url: string; sha256: string } | null;
};

export type UpdateOpts = {
  guest: Guest;
  unit: string | null;
  waitPort(): Promise<{ ok: boolean } | null>;
  target: UpdateTarget;
  now?: () => Date;
  sleep?: (ms: number) => Promise<void>;
  /** How many times to read the log waiting for the version banner + "Server started". */
  logPolls?: number;
};

export type UpdateResult = {
  status: "updated" | "already-current" | "refused" | "failed";
  applied: string[];
  notes: string[];
  backup?: string;
  rolledBack?: boolean;
  restarted?: boolean;
  /** "mirror" | "registry" | "present" */
  imageSource?: string;
};

const GB = 1024 ** 3;
const stamp = (d: Date) => d.toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");

type Insp = { image: string; env: Map<string, string>; cmd: string[]; binds: string[] };

async function inspectContainer(g: Guest, name: string): Promise<Insp | null> {
  const r = await g.exec(`docker inspect ${shq(name)} --format '{{json .}}'`);
  if (r.code !== 0) return null;
  try {
    const o = JSON.parse(r.stdout.trim());
    const env = new Map<string, string>();
    for (const e of (o.Config?.Env ?? []) as string[]) {
      const i = e.indexOf("=");
      if (i > 0) env.set(e.slice(0, i), e.slice(i + 1));
    }
    return { image: String(o.Config?.Image ?? ""), env, cmd: (o.Config?.Cmd ?? []) as string[], binds: (o.HostConfig?.Binds ?? []) as string[] };
  } catch {
    return null;
  }
}

async function imageId(g: Guest, ref: string): Promise<string | null> {
  const r = await g.exec(`docker image inspect ${shq(ref)} --format '{{.Id}}'`);
  const id = r.stdout.trim();
  return r.code === 0 && /^sha256:[a-f0-9]{64}$/.test(id) ? id : null;
}

/** Get the target image onto the guest. Returns where it came from, or an error string. */
async function ensureImage(g: Guest, t: UpdateTarget): Promise<{ ok: true; source: string } | { ok: false; error: string }> {
  const ref = terrariaImageRef(t.tshock);
  const have = await imageId(g, ref);
  if (have && (!t.imageId || have === t.imageId)) return { ok: true, source: "present" };
  let source = "";
  if (t.mirror) {
    const tar = "/root/nx-tshock-image.tar";
    const dl = await g.exec(`curl -fsSL --retry 3 --max-time 900 -o ${tar} ${shq(t.mirror.url)}`, 960_000);
    const sum = dl.code === 0 ? await g.exec(`echo ${shq(`${t.mirror.sha256}  ${tar}`)} | sha256sum -c -`) : null;
    const loaded = sum && sum.code === 0 ? await g.exec(`docker load -i ${tar}`, 600_000) : null;
    await g.exec(`rm -f ${tar}`).catch(() => undefined);
    if (loaded && loaded.code === 0) source = "mirror";
  }
  if (!source) {
    // Registry fallback. By digest when we know it (immutable), then tag it with the explicit version.
    const k = terrariaKnown(t.tshock);
    if (k && t.indexDigest) {
      const by = terrariaImageByDigest({ ...k, indexDigest: t.indexDigest });
      const p = await g.exec(`docker pull ${shq(by)}`, 900_000);
      if (p.code === 0 && (await g.exec(`docker tag ${shq(by)} ${shq(ref)}`)).code === 0) source = "registry";
    } else {
      const p = await g.exec(`docker pull ${shq(ref)}`, 900_000);
      if (p.code === 0) source = "registry";
    }
  }
  if (!source) return { ok: false, error: "Could not download the new Terraria server image, so nothing was changed." };
  const got = await imageId(g, ref);
  if (!got) return { ok: false, error: "The new Terraria server image did not load, so nothing was changed." };
  if (t.imageId && got !== t.imageId) {
    return { ok: false, error: "The downloaded server image did not match the expected build, so it was not used. Nothing was changed." };
  }
  return { ok: true, source };
}

