    container: C,
    unit: o.unit,
    image: newImage,
    env: (oldCmd) => (terrariaCmdIsOfficial(oldCmd) ? {} : { WORLD_FILENAME: null }),
    cmd: (old) => (terrariaCmdIsOfficial(old) ? old : terrariaOfficialCmd(old, worldFile)),
    binds: () => binds,
    envFile,
    waitPort: o.waitPort,
    afterStop: async () => {
      const cp = await g.exec(`cp -a ${shq(hostDir)} ${shq(backup)}`, 900_000);
      if (cp.code !== 0) {
        await g.exec(`rm -rf ${shq(backup)}`).catch(() => undefined);
        return "The safety backup of your world could not be made, so nothing was changed.";
      }
      const same = await g.exec(`diff -rq ${shq(hostDir)} ${shq(backup)}`, 600_000);
      if (same.code !== 0) {
        await g.exec(`rm -rf ${shq(backup)}`).catch(() => undefined);
        return "The safety backup of your world did not verify, so nothing was changed.";
      }
      await g.writeFile(`${backup}/NXEON-UPDATE.txt`, `Backup taken ${now().toISOString()} before moving from ${cur!.image} to ${newImage} (TShock ${t.tshock}, Terraria ${t.terraria}).\nRestore: stop the server, move ${hostDir} aside, copy this folder back to ${hostDir}.\n`).catch(() => undefined);
