        const verdict = judgeRunningVersions(parseTerrariaLog(logs.stdout), want);
        if (verdict.ok) {
          const world = await g.exec(`test -f ${shq(`${hostDir}/${worldFile}`)}`);
          if (world.code !== 0) return "The world file was not found after the update.";
          const up = await g.exec(`docker inspect -f '{{.State.Running}}' ${shq(C)}`);
          return up.stdout.trim() === "true" ? null : "The server stopped right after starting.";
