    };
  }
  if (r.status === "noop") {
    return { status: "already-current", applied: [], notes: [`This server already runs TShock ${t.tshock} (Terraria ${t.terraria}).`] };
  }
  const applied = [
    r.wasActive
      ? `Updated to TShock ${t.tshock} (Terraria ${t.terraria}) and confirmed from the server's own log that it is running with your world loaded.`
      : `Updated to TShock ${t.tshock} (Terraria ${t.terraria}). Your server is stopped, so it was left stopped; the new version starts the next time you start it.`,
  ];
  return {
    status: "updated",
    applied,
    notes: [...r.notes, `A full copy of your world and settings from just before the update is at ${backup} on your server.`, ...(r.wasActive ? ["Your server restarted briefly; connected players were disconnected and can rejoin now."] : [])],
    backup,
    restarted: r.wasActive,
    imageSource: img.source,
  };
}

// ---------------------------------------------------------------------------
// Drift (report only)
// ---------------------------------------------------------------------------

/** What a guest's terraria container is configured for and what its log says it runs. Read-only. */
export async function inspectTerrariaDrift(g: Guest, wanted?: string): Promise<DriftRow> {
  const cur = await inspectContainer(g, TERRARIA_CONTAINER);
  if (!cur) return judgeDrift({ image: null, wanted });
  const logs = await g.exec(`docker logs --tail 800 ${shq(TERRARIA_CONTAINER)} 2>&1`);
  return judgeDrift({ image: cur.image, logFacts: logs.code === 0 ? parseTerrariaLog(logs.stdout) : null, wanted });
}

