export function applyTerrariaImage(setupScript: string, plan: { version: string; mirror: { url: string; sha256: string } | null } | null | undefined): string {
  if (!plan || !/^\\d+\\.\\d+\\.\\d+$/.test(plan.version) || setupScript.includes("nx-tshock-image.tar")) return setupScript;
  const q = (s: string) => `'${s.replace(/'/g, `'\\\\''`)}'`;
