  if (plan.mirror && /^[a-f0-9]{64}$/.test(plan.mirror.sha256)) {
    const tar = "/root/nx-tshock-image.tar";
    const load = `{ curl -fsSL --retry 3 --max-time 900 -o ${tar} ${q(plan.mirror.url)} && echo ${q(`${plan.mirror.sha256}  ${tar}`)} | sha256sum -c - >/dev/null && docker load -i ${tar} >/dev/null; rm -f ${tar}; true; } && `;
