"use client";

import { useEffect, useState } from "react";

/**
 * Client view of /api/terraria-versions: the TShock/Terraria versions the platform offers
 * (catalogue refreshed by a sweep; built-in verified list until the first sweep). `null` while
 * loading or if the request fails, in which case the form keeps the schema's built-in options.
 */
export type TerrariaVersionRow = { tshock: string; terraria: string; released: string; notes: string; recommended: boolean; label: string; mirrored: boolean };

let shared: Promise<TerrariaVersionRow[] | null> | null = null;

function load(): Promise<TerrariaVersionRow[] | null> {
  shared ??= fetch("/api/terraria-versions")
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(String(r.status)))))
    .then((j: { versions?: TerrariaVersionRow[] }) => (Array.isArray(j.versions) && j.versions.length ? j.versions : null))
    .catch(() => {
      shared = null; // retry on next mount
      return null;
    });
  return shared;
}

export function useTerrariaVersions(enabled: boolean): TerrariaVersionRow[] | null {
  const [rows, setRows] = useState<TerrariaVersionRow[] | null>(null);
  useEffect(() => {
    if (!enabled) return;
    let live = true;
    load().then((r) => live && setRows(r));
    return () => {
      live = false;
    };
  }, [enabled]);
  return rows;
}
EOF
