/**
 * TShock image mirror sweep: refreshes the version catalogue (GitHub releases x registry tags),
 * downloads the images worth keeping as docker-archive tarballs onto the big disk, and REPORTS
 * releases the platform has not verified yet. See lib/terraria-mirror.ts for layout/retention and
 * lib/terraria-image.ts for why the image is what it is. Never deletes a mirrored file.
 *
 * Downloading uses `skopeo` (already on the primary; no docker daemon needed): linux/amd64 only,
 * exactly the manifest our guests run. After the copy the tarball's own config id is read back and
 * compared with the verified table, so a retagged/poisoned tag is quarantined instead of mirrored.
 *
 * Inert unless TERRARIA_MIRROR_SWEEP=on (or the admin script is run). Kill switch:
 * TERRARIA_MIRROR_DISABLED=1. Missing dataset root => no-op (the code never creates /tank/nxlabs-mirror).
 */
import { execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { TERRARIA_IMAGE_REPO, TERRARIA_PINNED_VERSION, terrariaImageRef, terrariaKnown } from "../lib/terraria-image";
import {
  ensureTerrariaRoot,
  planKeep,
  readTerrariaIndex,
  terrariaFileName,
  terrariaMirrorDisabled,
  terrariaMirrorRoot,
  terrariaSafeJoin,
  writeTerrariaIndex,
  type TerrariaIndex,
} from "../lib/terraria-mirror";
import { buildCatalogue, type GithubRelease } from "../lib/terraria-versions";

const UA = "NxeonTerrariaMirror/1.0 (+https://nxeon.cloud; ops@nxeon.cloud)";
const MAX_TAR_BYTES = 600 * 1024 * 1024;

export type RunResult = { code: number; stdout: string };
export type SweepDeps = {
  fetchImpl?: typeof fetch;
  /** Run a program (skopeo, tar). Injectable for tests. */
  run?: (cmd: string, args: string[], timeoutMs: number) => Promise<RunResult>;
  root?: string;
  /** TShock versions any server runs or is configured for (never dropped from the keep list). */
  inUse?: () => Promise<Set<string>>;
  keepNewest?: number;
  maxDownloads?: number;
  now?: () => Date;
};

export type SweepResult = {
  ok: boolean;
  skipped?: string;
  catalogue: string[];
  recommended: string | null;
  downloaded: string[];
  /** Releases with an image + a Terraria version that are NOT in TERRARIA_KNOWN_VERSIONS yet: add a row, then they become orderable. */
  unverified: string[];
  errors: string[];
};

const defaultRun = (cmd: string, args: string[], timeoutMs: number): Promise<RunResult> =>
  new Promise((resolve) => {
    execFile(cmd, args, { timeout: timeoutMs, maxBuffer: 16 * 1024 * 1024, encoding: "utf8" }, (err, stdout) => {
      resolve({ code: err ? ((err as NodeJS.ErrnoException & { code?: number | string }).code === "ENOENT" ? 127 : 1) : 0, stdout: String(stdout ?? "") });
    });
  });

async function sha256File(file: string): Promise<string> {
  const h = createHash("sha256");
  for await (const chunk of createReadStream(file)) h.update(chunk as Buffer);
  return h.digest("hex");
}

/** The image id (config digest) inside a docker-archive tarball, or null. */
export async function imageIdOfArchive(tar: string, run: NonNullable<SweepDeps["run"]>): Promise<string | null> {
  const r = await run("tar", ["-xOf", tar, "manifest.json"], 120_000);
  if (r.code !== 0) return null;
  try {
    const cfg = String(JSON.parse(r.stdout)?.[0]?.Config ?? "");
    const m = /^(?:blobs\/sha256\/)?([a-f0-9]{64})(?:\.json)?$/.exec(cfg);
    return m ? `sha256:${m[1]}` : null;
  } catch {
    return null;
  }
}

async function getJson(f: typeof fetch, url: string, headers: Record<string, string> = {}): Promise<unknown> {
  const r = await f(url, { headers: { "User-Agent": UA, Accept: "application/json", ...headers } });
  if (!r.ok) throw new Error(`HTTP ${r.status} for ${new URL(url).host}`);
  return r.json();
}

async function loadInUse(): Promise<Set<string>> {
  const out = new Set<string>([TERRARIA_PINNED_VERSION]);
  try {
    const { db } = await import("../lib/db");
    const rows = await db.server.findMany({ where: { osTemplate: { family: "terraria" } }, select: { gameConfig: true } });
    for (const r of rows) {
      const v = (r.gameConfig as Record<string, unknown> | null)?.["tshock-version"];
      if (typeof v === "string" && /^\d+\.\d+\.\d+$/.test(v)) out.add(v);
    }
  } catch {
    /* no DB (script run): pinned only */
  }
  return out;
}

export async function terrariaMirrorSweep(deps: SweepDeps = {}): Promise<SweepResult> {
  const res: SweepResult = { ok: false, catalogue: [], recommended: null, downloaded: [], unverified: [], errors: [] };
  if (terrariaMirrorDisabled()) return { ...res, ok: true, skipped: "TERRARIA_MIRROR_DISABLED=1" };
  const root = deps.root ?? terrariaMirrorRoot();
  const f = deps.fetchImpl ?? fetch;
  const run = deps.run ?? defaultRun;
  const now = deps.now ?? (() => new Date());
  try {
    await ensureTerrariaRoot(root);
  } catch {
    return { ...res, ok: true, skipped: "mirror dataset is not mounted (mirror off; guests pull from the registry)" };
  }

  const prev = (await readTerrariaIndex(root)) ?? { schema: 1 as const, updatedAt: now().toISOString(), versions: {} };
  const record = async (ix: TerrariaIndex, ok: boolean, error?: string) => {
    ix.updatedAt = now().toISOString();
    ix.lastSweep = { at: ix.updatedAt, ok, error: error ?? null };
    await writeTerrariaIndex(ix, root);
  };

  // 1. Catalogue
  let cat;
  try {
    const gh = process.env.GITHUB_TOKEN ? { Authorization: `Bearer ${process.env.GITHUB_TOKEN}` } : {};
    const releases = (await getJson(f, "https://api.github.com/repos/Pryaxis/TShock/releases?per_page=50", gh)) as GithubRelease[];
    const tok = (await getJson(f, `https://ghcr.io/token?scope=repository:${TERRARIA_IMAGE_REPO.replace("ghcr.io/", "")}:pull`)) as { token?: string };
    const tags = (await getJson(f, `https://ghcr.io/v2/${TERRARIA_IMAGE_REPO.replace("ghcr.io/", "")}/tags/list?n=2000`, { Authorization: `Bearer ${tok.token ?? ""}` })) as { tags?: string[] };
    cat = buildCatalogue(Array.isArray(releases) ? releases : [], tags.tags ?? []);
    if (!cat.length) throw new Error("catalogue came back empty");
  } catch (e) {
    const msg = `catalogue refresh failed: ${e instanceof Error ? e.message : String(e)}`;
    res.errors.push(msg);
    await record(prev, false, msg).catch(() => undefined);
    return res; // keep serving the previous catalogue
  }
  const ix: TerrariaIndex = { ...prev, versions: { ...prev.versions } };
  for (const e of cat) ix.versions[e.tshock] = { ...e, mirror: ix.versions[e.tshock]?.mirror ?? null, lastError: ix.versions[e.tshock]?.lastError ?? null };
  // a mirrored version that dropped out of the upstream list is kept (and no longer "recommended")
  for (const [v, row] of Object.entries(ix.versions)) if (!cat.some((e) => e.tshock === v)) ix.versions[v] = { ...row, recommended: false };
  res.catalogue = cat.map((e) => e.tshock);
  res.recommended = cat.find((e) => e.recommended)?.tshock ?? null;
  res.unverified = cat.filter((e) => !terrariaKnown(e.tshock)).map((e) => e.tshock);

  // 2. Download what is worth keeping and not yet mirrored (bounded per pass)
  const inUse = await (deps.inUse ?? loadInUse)();
  const wanted = planKeep(cat, { inUse, keepNewest: deps.keepNewest ?? 3 }).filter((v) => !ix.versions[v]?.mirror);
  for (const v of wanted.slice(0, deps.maxDownloads ?? 2)) {
    const tmp = path.join(root, ".tmp");
    const tmpFile = path.join(tmp, `${terrariaFileName(v)}.${process.pid}.part`);
    try {
      await fs.mkdir(tmp, { recursive: true });
      const cp = await run("skopeo", ["copy", "--override-os", "linux", "--override-arch", "amd64", `docker://${terrariaImageRef(v)}`, `docker-archive:${tmpFile}:${terrariaImageRef(v)}`], 20 * 60_000);
      if (cp.code !== 0) throw new Error(cp.code === 127 ? "skopeo is not installed" : "skopeo copy failed");
      const st = await fs.stat(tmpFile);
      if (st.size > MAX_TAR_BYTES) throw new Error("image is larger than the mirror's per-file limit");
      const id = await imageIdOfArchive(tmpFile, run);
      const expected = terrariaKnown(v)?.imageId ?? null;
      if (expected && id !== expected) throw new Error("image id does not match the verified table (quarantined, not mirrored)");
      const sha = await sha256File(tmpFile);
      const dest = terrariaSafeJoin(root, v, terrariaFileName(v));
      await fs.mkdir(path.dirname(dest), { recursive: true });
      await fs.rename(tmpFile, dest);
      ix.versions[v] = { ...ix.versions[v], lastError: null, mirror: { file: terrariaFileName(v), size: st.size, sha256: sha, imageId: id, mirroredAt: now().toISOString() } };
      res.downloaded.push(v);
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      res.errors.push(`${v}: ${msg}`);
      ix.versions[v] = { ...ix.versions[v], lastError: msg };
      await fs.rm(tmpFile, { force: true }).catch(() => undefined);
    }
  }
  res.ok = res.errors.length === 0;
  await record(ix, res.ok, res.errors.join("; ") || undefined);
  return res;
}

/** Fire-and-forget scheduler hook (worker/index.ts). Overlap-guarded; off unless TERRARIA_MIRROR_SWEEP=on. */
let busy = false;
export async function terrariaMirrorTick(): Promise<void> {
  if (busy || process.env.TERRARIA_MIRROR_SWEEP !== "on" || terrariaMirrorDisabled()) return;
  busy = true;
  try {
    const r = await terrariaMirrorSweep();
    console.log(
      `[terraria-mirror] ${r.skipped ? `skipped: ${r.skipped}` : `catalogue=${r.catalogue.join(",")} recommended=${r.recommended} downloaded=${r.downloaded.join(",") || "-"}`}` +
        (r.unverified.length ? ` UNVERIFIED-RELEASES=${r.unverified.join(",")} (add rows to TERRARIA_KNOWN_VERSIONS)` : "") +
        (r.errors.length ? ` errors=${r.errors.join("; ")}` : ""),
    );
  } catch (e) {
    console.error("[terraria-mirror] tick error", e instanceof Error ? e.message : e);
  } finally {
    busy = false;
  }
}
