/**
 * GAME_UPDATE for Terraria: move ONE server to a TShock/Terraria version through the safe update path
 * (worker/terraria-update.ts: backup, mirror/registry image, recreate, verify, roll back).
 *
 * How it is triggered (nothing here runs by itself):
 *   - the owner/admin enqueues  { type: "GAME_UPDATE", serverId, payload: { terrariaUpdate: true, version?: "6.2.1" } }
 *     (scripts/terraria-enqueue-update.ts does exactly that, one server at a time), or
 *   - the automatic 6-hourly sweep, ONLY if NXEON_TERRARIA_AUTO_UPDATE=on (default off) and the
 *     customer opted into auto-update; it then targets the mirror's recommended version.
 * `version` defaults to the recommended version in the mirror catalogue, else the pinned one.
 */
import type { Job } from "@prisma/client";
import { db } from "../lib/db";
import { withServerSsh } from "../lib/ssh-exec";
import { controlSpec } from "../lib/game-control";
import { startWindowMs } from "../lib/game-power-start";
import { TERRARIA_PINNED_VERSION } from "../lib/terraria-image";
import { readTerrariaIndex } from "../lib/terraria-mirror";
import type { SftpServer } from "../lib/sftp";
import { noRetry, waitForGamePort, type ControlServer } from "./game-control";
import { notifyAdmins } from "./monitor";
import { resolveTerrariaUnit, sshGuest } from "./terraria-guest";
import { resolveTerrariaTarget } from "./terraria-target";
import { terrariaImageUpdate, type UpdateResult } from "./terraria-update";

type Srv = { id: string; hostname: string; userId: string };

export async function terrariaUpdateJob(job: Job, server: Srv & Record<string, unknown>, href: string): Promise<void> {
  const payload = (job.payload ?? {}) as { terrariaUpdate?: boolean; version?: string };
  const ix = await readTerrariaIndex().catch(() => null);
  const recommended = Object.values(ix?.versions ?? {}).find((v) => v.recommended)?.tshock ?? TERRARIA_PINNED_VERSION;
  const version = payload.version && /^\d+\.\d+\.\d+$/.test(payload.version) ? payload.version : recommended;
  const target = await resolveTerrariaTarget(version);
  const record = (msg: string) =>
    db.gameRuntime
      .upsert({ where: { serverId: server.id }, create: { serverId: server.id, lastUpdateAt: new Date(), lastUpdateResult: msg.slice(0, 1000) }, update: { lastUpdateAt: new Date(), lastUpdateResult: msg.slice(0, 1000) } })
      .catch((e) => console.error("[terraria-update] could not record result", e));
  const notify = (title: string, body: string) => db.notification.create({ data: { userId: server.userId, title, body, href } }).catch(() => undefined);
  if (!target) {
    const msg = `TShock ${version} is not available on our servers, so nothing was updated.`;
    await record(msg);
    throw new Error(`terraria update: ${msg}`);
  }

  const spec = controlSpec("terraria");
  const r: UpdateResult = await withServerSsh(server as unknown as SftpServer, async (conn) =>
    terrariaImageUpdate({
      guest: sshGuest(conn),
      unit: await resolveTerrariaUnit(conn),
      target,
      waitPort: () => waitForGamePort(server as unknown as ControlServer, Math.max(60_000, spec ? startWindowMs(spec) : 0), 5_000),
    }),
  );

  const summary = [...r.applied, ...r.notes].join(" ");
  await record(summary);
  const audit = (action: string) => db.auditLog.create({ data: { userId: null, action, detail: `${server.hostname} terraria -> ${version} status=${r.status} backup=${r.backup ?? "-"}` } }).catch(() => undefined);

  if (r.status === "updated") {
    await audit("gameserver.terraria_update");
    // Keep the Settings picker truthful: the stored choice now matches what runs.
    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
    await db.server.update({ where: { id: server.id }, data: { gameConfig: { ...((fresh?.gameConfig as Record<string, unknown> | null) ?? {}), "tshock-version": version } as never } }).catch(() => undefined);
    await notify(`Terraria updated to TShock ${version} on ${server.hostname}`, summary);
    return;
  }
  if (r.status === "already-current") return;
  await audit("gameserver.terraria_update_failed");
  await notify(`Terraria update not applied on ${server.hostname}`, summary);
  if (r.status === "failed" && r.rolledBack === false) await notifyAdmins(`Terraria update left ${server.hostname} needing attention`, summary, `/admin/servers/${server.id}`).catch(() => undefined);
  await noRetry(job.id); // a retry would repeat the same backup + attempt
  throw new Error(`terraria update ${r.status}: ${summary}`.slice(0, 900));
}
