import type { ExecResult, Guest } from "../worker/game-config-appliers/types";
import { fakeGuest, tokenize, type FakeOpts } from "./_fake-docker-guest";
import { TERRARIA_PINNED, terrariaImageRef } from "../lib/terraria-image";

/**
 * fakeGuest + the extra commands the Terraria update path sends: image inspect/pull/load/tag, directory
 * copy/move/remove/diff/size, df, and `docker logs` (the version banner differs per image).
 */
export const LEGACY_LOG = "Terraria Server v1.4.5.6\nTShock 6.1.0.0 (Aceofspades) now running.\nServer started\n";
export const NEW_LOG = "Terraria Server v1.4.5.8\nTShock 6.2.1.0 (Bonfire) now running.\nLoading world nxeon\nServer started\n";

export type UpdFakeOpts = FakeOpts & {
  avail?: number;
  pullFails?: boolean;
  mirrorDownloadFails?: boolean;
  badChecksum?: boolean;
  /** the id a pulled/loaded image reports (default: the pinned table's) */
  loadedImageId?: string;
  copyFails?: boolean;
  diffFails?: boolean;
  /** log text the NEW container prints (default NEW_LOG) */
  newLog?: string;
  /** when the new container's log is read, simulate TShock having touched the data */
  newContainerDirtiesData?: boolean;
};

export function updFake(opts: UpdFakeOpts = {}) {
  const files0: Record<string, string> = {
    "/opt/terraria/nxeon.wld": "WORLD-BYTES",
    "/opt/terraria/config.json": '{"Settings":{"MaxSlots":8}}',
    "/opt/terraria/tshock.sqlite": "SQLITE-6.1",
    ...(opts.files ?? {}),
  };
  const base = fakeGuest({ ...opts, files: files0 });
  const { files, containers } = base;
  // the fake's default container is legacy; give it the legacy env/cmd the real one has
  const legacy = containers.get("terraria")!;
  legacy.image = "ryshe/terraria:latest";
  const images = new Map<string, string>([["ryshe/terraria:latest", "sha256:" + "1".repeat(64)]]);
  const pinned = TERRARIA_PINNED();
  const wantId = opts.loadedImageId ?? pinned.imageId;
  const calls: string[] = [];
  const ok = (stdout = ""): ExecResult => ({ code: 0, stdout, stderr: "" });
  const bad = (stderr = "err", code = 1): ExecResult => ({ code, stdout: "", stderr });
  const under = (dir: string) => [...files.keys()].filter((k) => k === dir || k.startsWith(dir + "/"));
  const snapshot = () => Object.fromEntries(under("/opt/terraria").sort().map((k) => [k, files.get(k)!]));

  const exec = async (cmd: string, t?: number): Promise<ExecResult> => {
    calls.push(cmd);
    const tk = tokenize(cmd.replace(/ 2>&1$/, "").replace(/ 2>\/dev\/null/g, ""));
    if (tk[0] === "docker" && tk[1] === "image" && tk[2] === "inspect" && cmd.includes("{{.Id}}")) {
      const id = images.get(tk[3]);
      return id ? ok(id + "\n") : bad("No such image");
    }
    if (tk[0] === "docker" && tk[1] === "pull") return opts.pullFails ? bad("pull failed") : (images.set(tk[2], wantId), ok());
    if (tk[0] === "docker" && tk[1] === "tag") { const id = images.get(tk[2]); if (!id) return bad(); images.set(tk[3], id); return ok(); }
    if (tk[0] === "curl") return opts.mirrorDownloadFails ? bad("curl failed", 22) : (files.set("/root/nx-tshock-image.tar", "TAR"), ok());
    if (cmd.includes("sha256sum -c")) return opts.badChecksum ? bad("FAILED") : ok();
    if (tk[0] === "docker" && tk[1] === "load") { images.set(terrariaImageRef(pinned.tshock), wantId); return ok(); }
    if (tk[0] === "du") return ok(String(under(tk[2]).reduce((n, k) => n + files.get(k)!.length, 0)) + "\n");
    if (tk[0] === "df") return ok(String(opts.avail ?? 200 * 1024 ** 3) + "\n");
    if (tk[0] === "cp" && tk[1] === "-a") {
      if (opts.copyFails && tk[3].includes("backup")) { files.set(tk[3] + "/partial", "x"); return bad("no space"); }
      for (const k of under(tk[2])) files.set(tk[3] + k.slice(tk[2].length), files.get(k)!);
      return ok();
    }
    if (tk[0] === "diff") {
      if (opts.diffFails) return bad("differ");
      const a = under(tk[2]).map((k) => [k.slice(tk[2].length), files.get(k)]);
      const b = under(tk[3]).map((k) => [k.slice(tk[3].length), files.get(k)]);
      return JSON.stringify(a.sort()) === JSON.stringify(b.sort()) ? ok() : bad("differ");
    }
    if (tk[0] === "mv") { for (const k of under(tk[1])) { files.set(tk[2] + k.slice(tk[1].length), files.get(k)!); files.delete(k); } return ok(); }
    if (tk[0] === "rm" && tk[1] === "-rf") { for (const k of under(tk[2])) files.delete(k); return ok(); }
    if (tk[0] === "docker" && tk[1] === "logs") {
      const c = containers.get("terraria");
      if (!c) return bad();
      if (c.image.startsWith("ryshe/")) return ok(LEGACY_LOG);
      if (opts.newContainerDirtiesData) files.set("/opt/terraria/nxeon.wld", "WORLD-SAVED-BY-NEW-TSHOCK");
      return ok(opts.newLog ?? NEW_LOG);
    }
    return base.guest.exec(cmd, t);
  };
  const guest: Guest = { exec, readFile: base.guest.readFile, writeFile: base.guest.writeFile };
  const initial = snapshot();
  // legacy container as provisioned: world file in env, plugin bind mount, -additionalplugins arg
  legacy.env = [...legacy.env.filter((e) => !e.startsWith("WORLD_FILENAME")), "WORLD_FILENAME=nxeon.wld"];
  return { ...base, guest, images, calls, snapshot, initial, under, pinned };
}
EOF
cat > test/terraria-update.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { terrariaImageUpdate, inspectTerrariaDrift } from "../worker/terraria-update";
import { NEW_LOG, LEGACY_LOG, updFake } from "./_fake-terraria-update";
import {
  TERRARIA_PINNED, TERRARIA_PINNED_VERSION, judgeDrift, judgeRunningVersions, parseTerrariaLog, terrariaImageRef,
  terrariaOfficialBinds, terrariaOfficialCmd, terrariaWorldFileOf, updateDirection, versionFromImage,
} from "../lib/terraria-image";

const pinned = TERRARIA_PINNED();
const target = (over: Record<string, unknown> = {}) => ({ tshock: pinned.tshock, terraria: pinned.terraria, imageId: pinned.imageId, indexDigest: pinned.indexDigest, mirror: null, ...over });
const NOW = () => new Date("2026-10-02T12:00:00Z");
const run = (g: ReturnType<typeof updFake>, t = target()) =>
  terrariaImageUpdate({ guest: g.guest, unit: g.unit, waitPort: async () => ({ ok: true }), target: t as never, now: NOW, sleep: async () => undefined, logPolls: 2 });
const BACKUP = "/opt/terraria-backup-pre-tshock-6.2.1-20261002T120000Z";

test("update from the legacy image: new image + contract, same ports/volumes, world untouched, backup made, verified from the log", async () => {
  const g = updFake();
  const r = await run(g, target({ mirror: { url: "https://nxeon.cloud/api/tshock-image/tok/6.2.1/tshock-6.2.1.tar", sha256: "b".repeat(64) } }));
  assert.equal(r.status, "updated", JSON.stringify(r));
  assert.equal(r.imageSource, "mirror");
  const c = g.containers.get("terraria")!;
  assert.equal(c.image, terrariaImageRef("6.2.1"));
  assert.ok(!c.image.includes("latest"));
  assert.deepEqual(c.cmd, ["-world", "/worlds/nxeon.wld", "-autocreate", "2", "-worldname", "Nxeon"]);
  assert.ok(!c.env.some((e) => e.startsWith("WORLD_FILENAME")), "legacy env var is gone");
  assert.deepEqual(c.binds, ["/opt/terraria:/server/tshock", "/opt/terraria:/tshock", "/opt/terraria:/worlds", "/opt/terraria-plugins:/plugins"].sort());
  assert.deepEqual(c.ports, { "7777/tcp": [{ HostIp: "", HostPort: "7777" }] });
  assert.equal(c.running, true);
  assert.equal(g.containers.has("terraria-old"), false, "old container removed after verification");
  assert.deepEqual(g.snapshot(), g.initial, "world, config and db are byte-identical");
  // backup: identical copy + manifest, taken before the new container existed
  for (const [k, v] of Object.entries(g.initial)) assert.equal(g.files.get(BACKUP + k.slice("/opt/terraria".length)), v);
  assert.match(g.files.get(`${BACKUP}/NXEON-UPDATE.txt`) ?? "", /ryshe\/terraria:latest/);
  assert.equal(r.backup, BACKUP);
  assert.ok(r.applied[0].includes("6.2.1") && r.applied[0].includes("1.4.5.8"));
  assert.ok(g.calls.findIndex((x) => x.startsWith("cp -a")) < g.calls.findIndex((x) => x.startsWith("docker create")), "backup precedes create");
  assert.ok(!g.files.has("/root/terraria.env"), "env file cleaned up");
});

test("mirror download failure falls back to a registry pull by digest and tags the explicit version", async () => {
  const g = updFake({ mirrorDownloadFails: true });
  const r = await run(g, target({ mirror: { url: "https://x/y.tar", sha256: "c".repeat(64) } }));
  assert.equal(r.status, "updated");
  assert.equal(r.imageSource, "registry");
  assert.ok(g.calls.some((c) => c.includes(`docker pull 'ghcr.io/pryaxis/tshock@${pinned.indexDigest}'`)));
  assert.ok(g.calls.some((c) => c.startsWith("docker tag")));
});

test("an image whose id is not the verified one is refused before anything is stopped", async () => {
  const g = updFake({ loadedImageId: "sha256:" + "9".repeat(64) });
  const r = await run(g);
  assert.equal(r.status, "refused");
  assert.match(r.notes.join(" "), /did not match the expected build/);
  assert.equal(g.containers.get("terraria")!.image, "ryshe/terraria:latest");
  assert.equal(g.st.active, true);
  assert.ok(!g.calls.some((c) => c.startsWith("systemctl stop")));
  assert.ok(!g.calls.some((c) => c.startsWith("cp -a")), "no backup noise either");
});

test("no download possible (mirror and registry both fail): refused, server never touched", async () => {
  const g = updFake({ mirrorDownloadFails: true, pullFails: true });
  const r = await run(g, target({ mirror: { url: "https://x", sha256: "d".repeat(64) } }));
  assert.equal(r.status, "refused");
  assert.ok(g.st.active && g.containers.get("terraria")!.running);
  assert.ok(!g.calls.some((c) => c.startsWith("systemctl stop")));
});

test("rollback when the new container will not start: old container back and running, data never touched", async () => {
  const g = updFake({ startFailsForNew: true });
  const r = await run(g);
  assert.equal(r.status, "failed");
  assert.equal(r.rolledBack, true);
  const c = g.containers.get("terraria")!;
  assert.equal(c.image, "ryshe/terraria:latest");
  assert.equal(c.running, true);
  assert.equal(g.st.active, true);
  assert.deepEqual(g.snapshot(), g.initial);
  assert.ok(!g.files.has("/opt/terraria-failed-20261002T120000Z/nxeon.wld"), "data was never restored over: the new one never ran");
  assert.match(r.notes.join(" "), /not lost/);
});

test("rollback when the log shows the wrong version: data folder restored from the backup, old container running again", async () => {
  const g = updFake({ newLog: LEGACY_LOG, newContainerDirtiesData: true });
  const r = await run(g);
  assert.equal(r.status, "failed");
  assert.equal(r.rolledBack, true);
  assert.match(r.notes.join(" "), /Verification failed/);
  assert.equal(g.containers.get("terraria")!.image, "ryshe/terraria:latest");
  assert.equal(g.containers.get("terraria")!.running, true);
  // the new TShock had rewritten the world: it was moved aside and the pre-update copy put back
  assert.deepEqual(g.snapshot(), g.initial);
  assert.equal(g.files.get("/opt/terraria-failed-20261002T120000Z/nxeon.wld"), "WORLD-SAVED-BY-NEW-TSHOCK");
});

test("rollback when TShock aborts startup (plugin / assembly error in the log)", async () => {
  const g = updFake({ newLog: "Terraria Server v1.4.5.8\nTShock 6.2.1.0 now running.\nStartup aborted: Could not load file or assembly 'X'\nServer started\n" });
  const r = await run(g);
  assert.equal(r.status, "failed");
  assert.equal(g.containers.get("terraria")!.image, "ryshe/terraria:latest");
  assert.deepEqual(g.snapshot(), g.initial);
});

test("a server the customer stopped is updated but stays stopped, and its log is not polled", async () => {
  const g = updFake({ active: false });
  const r = await run(g);
  assert.equal(r.status, "updated");
  const c = g.containers.get("terraria")!;
  assert.equal(c.image, terrariaImageRef("6.2.1"));
  assert.equal(c.running, false);
  assert.equal(g.st.active, false);
  assert.ok(!g.calls.some((x) => x.startsWith("systemctl start")));
  assert.ok(!g.calls.some((x) => x.startsWith("docker logs")));
  assert.match(r.applied[0], /left stopped/);
  assert.deepEqual(g.snapshot(), g.initial);
});

test("backup failure aborts before the new container exists and restarts the old one", async () => {
  const g = updFake({ copyFails: true });
  const r = await run(g);
  assert.equal(r.status, "failed");
  assert.match(r.notes.join(" "), /safety backup .* could not be made/);
  assert.equal(g.containers.get("terraria")!.image, "ryshe/terraria:latest");
  assert.equal(g.containers.get("terraria")!.running, true);
  assert.equal(g.st.created, 0);
  assert.ok(!g.under(BACKUP).length, "partial backup removed");
  assert.deepEqual(g.snapshot(), g.initial);
});

test("an unverifiable backup (diff mismatch) also aborts safely", async () => {
  const g = updFake({ diffFails: true });
  const r = await run(g);
  assert.equal(r.status, "failed");
  assert.equal(g.st.created, 0);
  assert.equal(g.containers.get("terraria")!.running, true);
});

test("not enough disk for a backup: refused with nothing stopped; a downgrade of the world is refused", async () => {
  const g = updFake({ avail: 1000 });
  const r = await run(g);
  assert.equal(r.status, "refused");
  assert.match(r.notes.join(" "), /not enough free disk space/);
  assert.ok(g.st.active && !g.calls.some((c) => c.startsWith("systemctl stop")));
  const g2 = updFake();
  const r2 = await run(g2, target({ tshock: "6.0.0", terraria: "1.4.5.5" }));
  assert.equal(r2.status, "refused");
  assert.match(r2.notes.join(" "), /cannot be taken back/);
});

test("a second run on an already-updated server is a no-op (already-current), nothing restarted", async () => {
  const g = updFake();
  assert.equal((await run(g)).status, "updated");
  const created = g.st.created;
  const r = await run(g);
  assert.equal(r.status, "already-current");
  assert.equal(g.st.created, created);
});

test("a legacy container whose world folder is not a host bind is refused (never guess)", async () => {
  const g = updFake();
  g.containers.get("terraria")!.binds = ["/opt/terraria-plugins:/tshock/CustomPlugins"];
  const r = await run(g);
  assert.equal(r.status, "refused");
  assert.ok(g.st.active);
});

test("a half-finished earlier run (only terraria-old exists) is healed first", async () => {
  const g = updFake();
  g.containers.set("terraria-old", g.containers.get("terraria")!);
  g.containers.delete("terraria");
  assert.equal((await run(g)).status, "updated");
});

// ---------------------------------------------------------------- pure helpers
test("version banner parsing + verdicts", () => {
  const f = parseTerrariaLog(NEW_LOG);
  assert.deepEqual([f.tshock, f.terraria, f.serverStarted, f.aborted], [["6.2.1.0"], ["1.4.5.8"], true, false]);
  assert.deepEqual(judgeRunningVersions(f, { tshock: "6.2.1", terraria: "1.4.5.8" }), { ok: true, tshock: "6.2.1.0", terraria: "1.4.5.8" });
