const manifest = (id: string) => JSON.stringify([{ Config: `${id.replace("sha256:", "")}.json`, RepoTags: ["x"] }]);
function fakeRun(imageIdFor: (v: string) => string, log: string[]) {
  return async (cmd: string, args: string[]) => {
    log.push(`${cmd} ${args.join(" ")}`);
    if (cmd === "skopeo") {
      const dst = args[args.length - 1].replace(/^docker-archive:/, "").split(":").slice(0, -2).join(":"); // path:ghcr.io/..:tag
      const v = args[args.length - 2].split(":").pop()!;
      await fs.writeFile(dst, TAR_BYTES + v);
