  { tag_name: "v6.9.9", published_at: "2026-10-01T00:00:00Z", prerelease: false, assets: [asset("6.9.9", "1.4.9.9")] },
];
const TAGS = ["latest", "stable", "5.2.4", "6.0.0", "6.1.0", "6.2.0", "6.2.1"]; // no 6.9.9 image yet, 6.2.0 has no release

test("catalogue: needs release AND image, skips pre-releases and pre-6.0, marks exactly one recommended, notes are plain", () => {
  const cat = buildCatalogue(RELEASES, TAGS);
  assert.deepEqual(cat.map((e) => e.tshock), ["6.2.1", "6.1.0", "6.0.0"]);
  assert.deepEqual(cat.map((e) => e.terraria), ["1.4.5.8", "1.4.5.6", "1.4.5.5"]);
  assert.equal(cat.filter((e) => e.recommended).length, 1);
  assert.equal(recommendedOf(cat)!.tshock, "6.2.1");
  assert.equal(cat[0].released, "2026-09-27");
  assert.ok(cat[0].verified && !cat[1].verified);
  assert.match(cat[0].notes, /^This version adds support for Terraria 1\.4\.5\.8\. Upgraded to OTAPI/);
  assert.ok(plainNotes("x".repeat(500)).length <= 280);
});
test("picker never offers a lower Terraria than the server runs", () => {
