test("retention: keep recommended + newest N + everything in use; in-use and recommended can never be evicted", () => {
  const cat = buildCatalogue(RELEASES, TAGS);
  assert.deepEqual(planKeep(cat, { inUse: new Set(["6.0.0"]), keepNewest: 1 }), ["6.2.1", "6.0.0"]);
  assert.equal(mayEvict("6.1.0", { inUse: new Set(["6.1.0"]), recommended: "6.2.1" }), false);
  assert.equal(mayEvict("6.2.1", { inUse: new Set(), recommended: "6.2.1" }), false);
  assert.equal(mayEvict("6.0.0", { inUse: new Set(["6.1.0"]), recommended: "6.2.1" }), true);
});

// ---- sweep with injected network + skopeo ---------------------------------------------------
const TAR_BYTES = "fake-docker-archive";
function fakeFetch(fail = false): typeof fetch {
  return (async (url: string) => {
    if (fail) return new Response("no", { status: 503 });
    const u = String(url);
    const body = u.includes("api.github.com") ? RELEASES : u.includes("/token") ? { token: "t" } : { tags: TAGS };
    return new Response(JSON.stringify(body), { status: 200 });
  }) as unknown as typeof fetch;
}
const manifest = (id: string) => JSON.stringify([{ Config: `${id.replace("sha256:", "")}.json`, RepoTags: ["x"] }]);
function fakeRun(imageIdFor: (v: string) => string, log: string[]) {
  return async (cmd: string, args: string[]) => {
    log.push(`${cmd} ${args.join(" ")}`);
    if (cmd === "skopeo") {
      const dst = args[args.length - 1].replace(/^docker-archive:/, "").split(":").slice(0, -2).join(":"); // path:ghcr.io/..:tag
      const v = args[args.length - 2].split(":").pop()!;
      await fs.writeFile(dst, TAR_BYTES + v);
      return { code: 0, stdout: "" };
    }
    if (cmd === "tar") {
      const v = (await fs.readFile(args[args.length - 2], "utf8")).slice(TAR_BYTES.length);
      return { code: 0, stdout: manifest(imageIdFor(v)) };
    }
    return { code: 1, stdout: "" };
  };
}

test("sweep: writes the catalogue, mirrors kept versions with checksum, reports unverified releases, never re-downloads, never deletes", async () => {
  const root = mkdtempSync(join(tmpdir(), "tsweep-"));
  const log: string[] = [];
  const idFor = (v: string) => (v === "6.2.1" ? pinned.imageId : "sha256:" + "a".repeat(64));
  const r = await terrariaMirrorSweep({ root, fetchImpl: fakeFetch(), run: fakeRun(idFor, log), inUse: async () => new Set(["6.1.0"]), keepNewest: 1, now: () => new Date("2026-10-02T00:00:00Z") });
  assert.equal(r.ok, true, JSON.stringify(r));
  assert.deepEqual(r.catalogue, ["6.2.1", "6.1.0", "6.0.0"]);
  assert.equal(r.recommended, "6.2.1");
  assert.deepEqual(r.downloaded.sort(), ["6.1.0", "6.2.1"]);
  assert.deepEqual(r.unverified, ["6.1.0", "6.0.0"], "releases missing from TERRARIA_KNOWN_VERSIONS are reported, report only");
  const ix = (await readTerrariaIndex(root))!;
  const m = ix.versions["6.2.1"].mirror!;
  const bytes = await fs.readFile(join(root, "6.2.1", "tshock-6.2.1.tar"));
  assert.equal(m.sha256, createHash("sha256").update(bytes).digest("hex"));
  assert.equal(m.size, bytes.length);
  assert.equal(m.imageId, pinned.imageId);
  assert.equal(ix.versions["6.0.0"].mirror, null, "not kept: not recommended, not newest, not in use");
  assert.ok(log.some((l) => l.includes("--override-arch amd64")));
  assert.equal(ix.lastSweep?.ok, true);
  // second pass: nothing to download, nothing removed
  log.length = 0;
  const r2 = await terrariaMirrorSweep({ root, fetchImpl: fakeFetch(), run: fakeRun(idFor, log), inUse: async () => new Set(["6.1.0"]), keepNewest: 1 });
  assert.deepEqual(r2.downloaded, []);
  assert.ok(!log.some((l) => l.startsWith("skopeo")));
  assert.ok((await fs.stat(join(root, "6.1.0", "tshock-6.1.0.tar"))).isFile());
});

test("sweep: an image whose id differs from the verified table is quarantined, not mirrored", async () => {
  const root = mkdtempSync(join(tmpdir(), "tsweep-"));
  const r = await terrariaMirrorSweep({ root, fetchImpl: fakeFetch(), run: fakeRun(() => "sha256:" + "e".repeat(64), []), inUse: async () => new Set(), keepNewest: 1 });
  assert.equal(r.ok, false);
  assert.match(r.errors.join(" "), /6\.2\.1: image id does not match/);
  const ix = (await readTerrariaIndex(root))!;
  assert.equal(ix.versions["6.2.1"].mirror, null);
  await assert.rejects(fs.stat(join(root, "6.2.1", "tshock-6.2.1.tar")));
  assert.deepEqual((await fs.readdir(join(root, ".tmp"))).filter((f) => f.endsWith(".part")), []);
});

