test("serving: only a valid token for a mirrored, intact file; ranges + etag; everything else is 404", async () => {
  const root = mkdtempSync(join(tmpdir(), "tserve-"));
  await terrariaMirrorSweep({ root, fetchImpl: fakeFetch(), run: fakeRun((v) => (v === "6.2.1" ? pinned.imageId : "sha256:" + "a".repeat(64)), []), inUse: async () => new Set(), keepNewest: 1 });
  const file = "tshock-6.2.1.tar";
  const path = terrariaMirrorPath("6.2.1", file).replace("/api/tshock-image/", "").split("/");
  const get = (segs: string[], headers: Record<string, string> = {}) => serveTerrariaImage(new Request("https://nxeon.cloud/x", { headers }), segs, { root, rateLimit: false });
  const ok = await get(path);
  assert.equal(ok.status, 200);
  assert.equal((await ok.text()).startsWith(TAR_BYTES), true);
  const etag = ok.headers.get("etag")!;
  assert.equal((await get(path, { "if-none-match": etag })).status, 304);
  const part = await get(path, { range: "bytes=0-3" });
  assert.equal(part.status, 206);
  assert.equal(await part.text(), TAR_BYTES.slice(0, 4));
  assert.equal((await get(["x".repeat(32), "6.2.1", file])).status, 404, "bad token");
  assert.equal((await get([path[0], "6.1.0", file])).status, 404, "token is per file");
  assert.equal((await get([path[0], "6.2.1", "..%2Findex.json"])).status, 404);
  assert.equal((await get([path[0], "../6.2.1", file])).status, 404);
  assert.throws(() => terrariaSafeJoin(root, "6.2.1", "../index.json"));
  // truncated on disk -> treated as absent
  await fs.writeFile(join(root, "6.2.1", file), "x");
  assert.equal((await get(path)).status, 404);
  assert.match(terrariaMirrorUrl("6.2.1"), /^https:\/\/nxeon\.cloud\/api\/tshock-image\/[A-Za-z0-9_-]{32}\/6\.2\.1\/tshock-6\.2\.1\.tar$/);
});

