// ---- plugin installer sees both layouts -------------------------------------------------------
function shellFor(inspect: { cmd: string; entry: string; mounts: Record<string, { src: string; type: string }> }) {
  const dir = mkdtempSync(join(tmpdir(), "tdock-"));
  const plug = join(dir, "plugins");
  mkdirSync(plug);
  const mountSrc = (dest: string) => (inspect.mounts[dest] ? plug : "");
  writeFileSync(join(dir, "docker"), `#!/bin/sh
case "$*" in
  *"json .Config.Cmd"*) printf '%s' '${inspect.cmd}';;
  *"json .Config.Entrypoint"*) printf '%s' '${inspect.entry}';;
  *'Destination "/tshock/CustomPlugins"'*) printf '%s' '${mountSrc("/tshock/CustomPlugins")}';;
  *'Destination "/plugins"'*) printf '%s' '${mountSrc("/plugins")}';;
esac
`);
  chmodSync(join(dir, "docker"), 0o755);
  const out = execFileSync("sh", ["-c", terrariaPluginDirShell()], { env: { ...process.env, PATH: `${dir}:${process.env.PATH}` }, encoding: "utf8" }).trim();
  return { out, plug };
}
test("plugin folder detection: legacy mount+flag, official /plugins bind, and nothing when neither is there", () => {
  const legacy = shellFor({ cmd: '["-autocreate","2","-additionalplugins","/tshock/CustomPlugins"]', entry: '["/bin/sh","bootstrap.sh"]', mounts: { "/tshock/CustomPlugins": { src: "x", type: "bind" } } });
  assert.equal(legacy.out, legacy.plug);
  const official = shellFor({ cmd: '["-world","/worlds/nxeon.wld"]', entry: '["./TShock.Server","-additionalplugins","/plugins"]', mounts: { "/plugins": { src: "x", type: "bind" } } });
  assert.equal(official.out, official.plug);
  const neither = shellFor({ cmd: '["-world","/worlds/nxeon.wld"]', entry: '["./TShock.Server","-additionalplugins","/plugins"]', mounts: {} });
  assert.equal(neither.out, "");
  assert.ok(TERRARIA_PLUGIN_HOST_DIR);
});
